using System.Text.Json; using backend.Data; using backend.Extensions; using backend.Models; using backend.Security; using backend.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace backend.Controllers;
[ApiController,Authorize,Route("api/payments"),Tags("Payments")]
public class PaymentsController(CrmDbContext db,IFinancialService financial,IOneSignalNotificationService push) : ControllerBase
{
 [HttpGet,RequirePermission(PermissionCodes.PaymentsView)] public async Task<ActionResult> Get([FromQuery]int page=1,[FromQuery]int pageSize=50,[FromQuery]int? customerId=null,[FromQuery]int? salesExecutiveId=null,[FromQuery]PaymentStatus? status=null){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Payments.Include(x=>x.Customer).Include(x=>x.SalesExecutive).AsQueryable();if(customerId.HasValue)q=q.Where(x=>x.CustomerId==customerId);if(salesExecutiveId.HasValue)q=q.Where(x=>x.SalesExecutiveId==salesExecutiveId);if(status.HasValue)q=q.Where(x=>x.Status==status);var total=await q.CountAsync();var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.CustomerId,Customer=x.Customer.Name,x.CollectionNumber,x.SalesExecutiveId,SalesExecutive=x.SalesExecutive.FullName,x.Amount,x.PaymentDate,x.Method,x.TransactionReference,x.InstallmentId,x.Status,x.ProofUrl,x.Remarks,x.IsReversed,x.ReversalReason,x.CreatedAt}).ToListAsync();return Ok(new{items,total,page,pageSize});}
 [HttpPost,RequirePermission(PermissionCodes.PaymentsRecord)] public async Task<ActionResult> Record(RecordPaymentRequest r,[FromHeader(Name="Idempotency-Key")]string? key){if(r.Amount<=0)return BadRequest(new{message="Payment amount must be greater than zero."});if(string.IsNullOrWhiteSpace(key))return BadRequest(new{message="Idempotency-Key header is required."});var existing=await db.Payments.SingleOrDefaultAsync(x=>x.IdempotencyKey==key);if(existing!=null)return Ok(new{existing.Id,duplicate=true});var customer=await db.Customers.Include(x=>x.FinancialAgreement).SingleOrDefaultAsync(x=>x.Id==r.CustomerId);if(customer?.FinancialAgreement is null)return BadRequest(new{message="Customer financial agreement is required."});var before=await financial.SummaryAsync(r.CustomerId);if(r.Amount>before.OutstandingBalance)return BadRequest(new{message="Payment exceeds outstanding balance."});if(r.InstallmentId.HasValue&&!await db.EmiInstallments.AnyAsync(x=>x.Id==r.InstallmentId&&x.FinancialAgreement.CustomerId==r.CustomerId))return BadRequest(new{message="Installment does not belong to customer."});await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var payment=new Payment{CustomerId=r.CustomerId,CollectionNumber=$"COL-{DateTime.UtcNow:yyyyMMddHHmmss}-{Guid.NewGuid():N}"[..31],SalesExecutiveId=customer.AssignedToId??User.UserId(),Amount=r.Amount,PaymentDate=r.PaymentDate.ToUniversalTime(),Method=r.Method,TransactionReference=r.TransactionReference,InstallmentId=r.InstallmentId,ProofUrl=r.ProofUrl,Remarks=r.Remarks,Status=PaymentStatus.Approved,SubmittedById=User.UserId(),VerifiedById=User.UserId(),VerifiedAt=DateTime.UtcNow,IdempotencyKey=key};db.Add(payment);db.FinancialAuditLogs.Add(new FinancialAuditLog{CustomerId=r.CustomerId,PaymentId=payment.Id,Action=FinancialAuditAction.PaymentRecorded,DetailsJson=JsonSerializer.Serialize(r),PerformedById=User.UserId()});try{await db.SaveChangesAsync();await financial.RecalculateInstallmentsAsync(customer.FinancialAgreement.Id);var after=await financial.SummaryAsync(r.CustomerId);await AddBalanceNotification(customer,before,after,$"balance:payment:{payment.Id}");await db.SaveChangesAsync();await tx.CommitAsync();return Created($"/api/payments/{payment.Id}",new{payment.Id});}catch(DbUpdateException){await tx.RollbackAsync();return Conflict(new{message="Duplicate or concurrent payment submission detected."});}}
 [HttpPost("{id:int}/reverse"),RequirePermission(PermissionCodes.PaymentsReverse)] public async Task<ActionResult> Reverse(int id,ReasonRequest r){if(string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Reversal reason is required."});await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var p=await db.Payments.Include(x=>x.Customer).ThenInclude(x=>x.FinancialAgreement).SingleOrDefaultAsync(x=>x.Id==id);if(p is null)return NotFound();if(p.IsReversed)return Conflict(new{message="Payment already reversed."});var before=await financial.SummaryAsync(p.CustomerId);p.IsReversed=true;p.ReversedAt=DateTime.UtcNow;p.ReversedById=User.UserId();p.ReversalReason=r.Reason.Trim();db.FinancialAuditLogs.Add(new FinancialAuditLog{CustomerId=p.CustomerId,PaymentId=p.Id,Action=FinancialAuditAction.PaymentReversed,DetailsJson=JsonSerializer.Serialize(r),PerformedById=User.UserId()});await db.SaveChangesAsync();if(p.Customer.FinancialAgreement!=null)await financial.RecalculateInstallmentsAsync(p.Customer.FinancialAgreement.Id);var after=await financial.SummaryAsync(p.CustomerId);await AddBalanceNotification(p.Customer,before,after,$"balance:reversal:{p.Id}");await db.SaveChangesAsync();await tx.CommitAsync();return Ok(after);}
 private async Task AddBalanceNotification(Customer c,FinancialSummary before,FinancialSummary after,string eventKey){if(c.AssignedToId is null||before.OutstandingBalance==after.OutstandingBalance)return;var message=$"{c.Name}'s outstanding balance is now {after.OutstandingBalance:0.00}.";db.AppNotifications.Add(new AppNotification{UserId=c.AssignedToId.Value,CustomerId=c.Id,CustomerName=c.Name,FileId=c.FileId,Title="Customer balance updated",Message=message,Type="OutstandingBalanceChanged",Screen="customer",DueAmount=after.CurrentDue,OutstandingBalance=after.OutstandingBalance,EventKey=eventKey});await push.SendFinancialPushAsync(c.AssignedToId.Value,c.Id,"Customer balance updated",message,HttpContext.RequestAborted);}
 [HttpPost("{id:int}/approve"),RequirePermission(PermissionCodes.PaymentsApprove)] public async Task<ActionResult> Approve(int id){var p=await db.Payments.Include(x=>x.Customer).ThenInclude(x=>x.FinancialAgreement).SingleOrDefaultAsync(x=>x.Id==id);if(p is null)return NotFound();if(p.Status==PaymentStatus.Approved)return Ok(new{message="Already approved."});if(p.Status==PaymentStatus.Rejected||p.IsReversed)return Conflict(new{message="Rejected or reversed payment cannot be approved."});var summary=await financial.SummaryAsync(p.CustomerId);if(p.Amount>summary.OutstandingBalance)return BadRequest(new{message="Payment exceeds outstanding balance."});p.Status=PaymentStatus.Approved;p.VerifiedById=User.UserId();p.VerifiedAt=DateTime.UtcNow;db.FinancialAuditLogs.Add(new FinancialAuditLog{CustomerId=p.CustomerId,PaymentId=p.Id,Action=FinancialAuditAction.PaymentApproved,PerformedById=User.UserId()});await db.SaveChangesAsync();if(p.Customer.FinancialAgreement!=null)await financial.RecalculateInstallmentsAsync(p.Customer.FinancialAgreement.Id);return Ok(new{message="Payment approved."});}
 [HttpPost("{id:int}/reject"),RequirePermission(PermissionCodes.PaymentsApprove)] public async Task<ActionResult> Reject(int id,ReasonRequest r){if(string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Reason is required."});var p=await db.Payments.FindAsync(id);if(p is null)return NotFound();if(p.Status!=PaymentStatus.Pending)return Conflict(new{message="Only pending payments can be rejected."});p.Status=PaymentStatus.Rejected;p.RejectReason=r.Reason.Trim();p.VerifiedById=User.UserId();p.VerifiedAt=DateTime.UtcNow;db.FinancialAuditLogs.Add(new FinancialAuditLog{CustomerId=p.CustomerId,PaymentId=p.Id,Action=FinancialAuditAction.PaymentRejected,DetailsJson=JsonSerializer.Serialize(r),PerformedById=User.UserId()});await db.SaveChangesAsync();return Ok(new{message="Payment rejected."});}
 public record RecordPaymentRequest(int CustomerId,decimal Amount,DateTime PaymentDate,PaymentMethod Method,string? TransactionReference,int? InstallmentId,string? ProofUrl,string? Remarks);public record ReasonRequest(string Reason);
}
